import ru.screenrecorder.app.ReleasePolicy;import java.util.*;
public final class ReleasePolicyTest {
 static int count;static void check(boolean v,String name){if(!v)throw new AssertionError(name);System.out.println("PASS "+(++count)+". "+name);}
 static ReleasePolicy.Release r(String name,long date,long version,boolean stable,int min){return new ReleasePolicy.Release(name,date,version,min,0,stable);}
 public static void main(String[] args){ReleasePolicy.Release stable=r("stable",10,100,true,29),test=r("test",20,101,false,29),experimental=r("experimental",30,102,false,29);List<ReleasePolicy.Release> all=Arrays.asList(stable,test,experimental);
 check(ReleasePolicy.choose(all,false,35)==experimental,"Default includes newest experimental build");check(ReleasePolicy.choose(all,true,35)==stable,"Stable-only chooses older stable publication");check(ReleasePolicy.choose(Arrays.asList(test,experimental),true,35)==null,"No stable build produces no candidate");check(ReleasePolicy.choose(Arrays.asList(stable,test),false,35)==test,"Testing channel is allowed by default");check(ReleasePolicy.choose(Collections.emptyList(),false,35)==null,"Empty catalog");check(ReleasePolicy.choose(Arrays.asList(stable,r("future",40,103,false,36)),false,35)==stable,"Incompatible Android SDK is skipped");check(ReleasePolicy.choose(Arrays.asList(new ReleasePolicy.Release("old-os",40,103,29,32,false),stable),false,35)==stable,"Maximum SDK is respected");check(ReleasePolicy.choose(Arrays.asList(test,stable,experimental),false,35)==experimental,"Input ordering does not affect choice");check(ReleasePolicy.choose(Arrays.asList(r("higher-code",10,500,false,29),test),false,35)==test,"Publication date is authoritative");check(ReleasePolicy.choose(Arrays.asList(r("a",10,1,true,29),r("b",10,2,true,29)),true,35).version==2,"Equal publication times use version code");check(ReleasePolicy.choose(Arrays.asList(r("min",1,1,true,29)),false,29)!=null,"Minimum SDK boundary");check(ReleasePolicy.choose(Arrays.asList(r("min",1,1,true,30)),false,29)==null,"Older OS rejected");System.out.println(count+" selection checks passed");}
}
